create table if not exists channel_memory(id uuid primary key default gen_random_uuid(),channel_id uuid not null unique references channels(id) on delete cascade,data jsonb not null default '{}',version int not null default 1,updated_at timestamptz not null default now());
create table if not exists channel_memory_versions(id uuid primary key default gen_random_uuid(),channel_id uuid not null references channels(id) on delete cascade,version int not null,data jsonb not null,status text not null default 'active',created_at timestamptz not null default now(),unique(channel_id,version));
